{
  "rules": [
    "If sentiment is positive (≥0.2) in recent history, reduce forecast slope to avoid over-optimism.",
    "If forecast shows strong upward trend after a spike, cap growth rate to prevent overshoot.",
    "When true outcome deviates sharply from forecast, check if sentiment was neutral or negative — if so, adjust downward bias.",
    "For 30-day forecasts, if true values show mean reversion after a peak, model should not assume continuation of trend.",
    "If sentiment history contains multiple 0.00 entries, forecast should not be overly optimistic — use recent history mean as baseline.",
    "If forecast is consistently above true outcome, especially after a spike, apply downward correction proportional to sentiment magnitude."
  ]
}
